import { createContext, useContext } from "solid-js";
import { createStore } from "solid-js/store";

const InventoryModel = () => {
	const [state, setState] = createStore({
		containers: [
			{ id: "Bag1", maxCount: -1 },
			{ id: "Bag2", maxCount: -1 },
			{ id: "Slot1", maxCount: 1, alphaOnly: true },
			{ id: "Slot2", maxCount: 1, alphaOnly: true },
			{ id: "Slot3", maxCount: 1, alphaOnly: true },
			{ id: "Extras", maxCount: 3 },
		],

		items: [
			{ id: "A", cid: "Bag1" },
			{ id: "B", cid: "Slot2" },
			{ id: "C", cid: "Extras" },
			{ id: "D", cid: "Bag1" },
			{ id: "E", cid: "Bag1" },
			{ id: "F", cid: "Bag1" },
			{ id: "1", cid: "Bag2" },
			{ id: "3", cid: "Bag2" },
			{ id: "4", cid: "Bag2" },
			{ id: "5", cid: "Bag2" },
			{ id: "6", cid: "Bag2" },
		],
	});

	function contains(iid: string, cid: string) {
		const item = state.items.find((item) => item.id == iid);
		return item && item.cid == cid;
	}

	function canContain(iid: string, cid: string) {
		const container = state.containers.find((c) => c.id == cid);
		if (container == null) {
			return false;
		}

		if (container.maxCount != -1) {
			let count = 0;
			for (const item of state.items) {
				if (item.cid == cid) {
					count++;
				}
			}

			if (count >= container.maxCount) {
				return false;
			}
		}

		if (container.alphaOnly) {
			if (!Number.isNaN(parseInt(iid, 10))) {
				return false;
			}
		}

		return true;
	}

	function items(cid: string) {
		return state.items.filter((item) => item.cid == cid).map((item) => item.id);
	}

	function swapItems(aid: string, bid: string) {
		const itemA = state.items.find((item) => item.id == aid);
		const itemB = state.items.find((item) => item.id == bid);

		// If we cannot find either item, do nothing.
		if (itemA == null || itemB == null) {
			return;
		}

		// If they are in the same container, do nothing.
		if (itemA.cid == itemB.cid) {
			return;
		}

		const containerA = itemA.cid;
		const containerB = itemB.cid;
		// If the items cannot be swapped, do nothing.
		if (!canContain(aid, containerB) || !canContain(bid, containerA)) {
			return;
		}

		setState("items", (item) => item.id == aid, "cid", containerB);
		setState("items", (item) => item.id == bid, "cid", containerA);
	}

	function equipItem(iid: string, cid: string) {
		const item = state.items.find((item) => item.id == iid);
		const container = state.containers.find((c) => c.id == cid);

		// No item? do nothing.
		if (item == null) {
			return;
		}

		// No container? do nothing.
		if (container == null) {
			return;
		}

		// Already in container, do nothing.
		if (item.cid == cid) {
			return;
		}

		// If the container cannot hold it, do nothing.
		if (!canContain(iid, cid)) {
			return;
		}

		setState("items", (item) => item.id == iid, "cid", cid);
	}

	function unEquipItem(iid: string) {
		const item = state.items.find((item) => item.id == iid);

		// No item? do nothing.
		if (item == null) {
			return;
		}

		// Item already in inventory? do nothing.
		if (item.cid == "Bag1" || item.cid == "Bag2") {
			return;
		}

		// Let's put the item in bag with the least items.
		let bag1Count = 0;
		let bag2Count = 0;
		for (const item of state.items) {
			if (item.cid == "Bag1") {
				bag1Count++;
			} else if (item.cid == "Bag2") {
				bag2Count++;
			}
		}

		setState("items", (item) => item.id == iid, "cid", bag1Count > bag2Count ? "Bag2" : "Bag1");
	}

	function canAutoSlotItem(iid: string) {
		const item = state.items.find((e) => e.id == iid);
		if (item) {
			const slotIds = ["Slot1", "Slot2", "Slot3"];

			// Is it already in a slot?
			if (slotIds.includes(item.cid)) {
				return false;
			}

			// Is the slot empty and can this item slot into it?
			for (const cid of slotIds) {
				if (state.items.every((e) => e.cid != cid) && canContain(iid, cid)) {
					return true;
				}
			}
		}

		return false;
	}
	function autoSlotItem(iid: string) {
		const item = state.items.find((e) => e.id == iid);
		if (item) {
			const slotIds = ["Slot1", "Slot2", "Slot3"];

			// Is it already in a slot?
			if (slotIds.includes(item.cid)) {
				return;
			}

			// Is the slot empty and can this item slot into it?
			for (const cid of slotIds) {
				if (state.items.every((e) => e.cid != cid) && canContain(iid, cid)) {
					equipItem(iid, cid);
					return;
				}
			}
		}
	}

	return {
		state,
		setState,
		contains,
		canContain,
		items,
		swapItems,
		equipItem,
		unEquipItem,
		canAutoSlotItem,
		autoSlotItem,
	};
};

export const InventoryModelContext = createContext(InventoryModel());
export const useInventoryModel = () => useContext(InventoryModelContext);
